// 生成查询向量
const query = $json.search_query;
const apiKey = 'YOUR_OPENAI_API_KEY'; // 请替换为实际API密钥

// 使用已存储的示例向量（实际环境中应调用OpenAI API）
const queryVectors = {
  '机器学习技术': JSON.stringify(Array(1536).fill(0).map(() => Math.random() * 0.1 - 0.05)),
  '健康生活': JSON.stringify(Array(1536).fill(0).map(() => Math.random() * 0.1 - 0.05)),
  '经济发展': JSON.stringify(Array(1536).fill(0).map(() => Math.random() * 0.1 - 0.05)),
  '人工智能应用': JSON.stringify(Array(1536).fill(0).map(() => Math.random() * 0.1 - 0.05))
};

return {
  ...$json,
  query_embedding: queryVectors[query] || JSON.stringify(Array(1536).fill(0.01))
};
